def todas():
    out = list(R)
    for nom, pan, g in PANES_TOSTADA:
        for top, ing in TOPPINGS_TOSTADA:
            out.append((f'{nom} {top}', '🍞', 'desayuno', [(pan, g)] + ing))
    for top, ing in BOCADILLOS:
        out.append((f'Bocadillo de {top}', '🥖', 'bocadillo', [('pan de barra', 100)] + ing))
        out.append((f'Bocadillo integral de {top}', '🥖', 'bocadillo', [('pan integral', 100)] + ing))
    for nom, ing in SANDWICHES:
        out.append((nom, '🥪', 'bocadillo', ing))
    for base, bi in BASES_ENSALADA:
        for top, ti in TOPPINGS_ENSALADA:
            out.append((f'{base} {top}', '🥗', 'ensalada', bi + ti))
    for nom, e, ing in ENSALADAS_FIJAS:
        out.append((nom, e, 'ensalada', ing))
    for nom, ing, g, e in PROTEINAS_PLANCHA:
        out.append((nom, e, 'plato', [(ing, g), ('aceite de oliva', 5)]))
        for gn, gi in GUARNICIONES:
            out.append((f'{nom} {gn}', e, 'plato', [(ing, g), ('aceite de oliva', 5)] + gi))
    for pn, pi in PASTAS:
        for sn, si in SALSAS_PASTA:
            out.append((f'{pn} {sn}', '🍝', 'plato', [(pi, 90)] + si))
    for nom, ing in REVUELTOS:
        base = [('clara de huevo', 200), ('aceite de oliva', 3)] if 'claras' in nom else [('huevo', 110), ('aceite de oliva', 6)]
        out.append((nom, '🍳', 'plato', base + [x for x in ing if x[1] > 0]))
    vistos, final = set(), []
    for r in out:
        k = r[0].lower()
        if k in vistos: continue
        vistos.add(k); final.append(r)
    return final
